import React, { useState, useEffect, useRef } from 'react';
import { getUserRoles } from '../../keycloak';
import './MainFeed.css';

const MainFeed = () => {
    const [posts, setPosts] = useState([]);
    const [newPost, setNewPost] = useState({ type: 'text', title: '', content: '', url: '' });
    const [showAddForm, setShowAddForm] = useState(false);
    const [userRoles, setUserRoles] = useState([]);
    const [playingAudioId, setPlayingAudioId] = useState(null);
    const [volume, setVolume] = useState(0.7);
    const [playbackRate, setPlaybackRate] = useState(1.0);
    const [currentTime, setCurrentTime] = useState(0);
    const [duration, setDuration] = useState(0);
    const audioRef = useRef(null);
    const feedEndRef = useRef(null);
    const addFormRef = useRef(null);
    const [notification, setNotification] = useState(null);

    useEffect(() => {
        const savedPosts = localStorage.getItem('mainFeedPosts');
        if (savedPosts) {
            setPosts(JSON.parse(savedPosts));
        } else {
            const initialPosts = [
                {
                    id: 1,
                    type: 'text',
                    title: '📄 О стремлении человека не есть',
                    content: 'Понимание истинных потребностей тела и духа. Человек может существовать без физической пищи, черпая энергию из духовных источников.',
                    date: '2025-03-15',
                    author: 'Admin'
                },
                {
                    id: 2,
                    type: 'text',
                    title: '📄 Основа сила человека - дух',
                    content: 'Духовная сила - это основа всего. Развивая дух, мы развиваем себя.',
                    date: '2025-03-16',
                    author: 'Admin'
                },
                {
                    id: 3,
                    type: 'audio',
                    title: '🎵 Эфир - 01.01.2025',
                    content: 'Новогодний эфир. Подведение итогов и планы на будущее.',
                    url: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3',
                    date: '2025-01-01',
                    author: 'Admin'
                },
                {
                    id: 4,
                    type: 'audio',
                    title: '🎵 Эфир - 13.01.2025',
                    content: 'Практики дыхания и медитации.',
                    url: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3',
                    date: '2025-01-13',
                    author: 'Admin'
                },
                {
                    id: 5,
                    type: 'audio',
                    title: '🎵 Эфир - 22.01.2025',
                    content: 'Сила движения и его значение в жизни.',
                    url: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-3.mp3',
                    date: '2025-01-22',
                    author: 'Admin'
                },
                {
                    id: 6,
                    type: 'text',
                    title: '📄 Значение движения',
                    content: 'Движение - это жизнь. Ежедневная физическая активность необходима для поддержания здоровья и энергии.',
                    date: '2025-03-17',
                    author: 'Admin'
                },
                {
                    id: 7,
                    type: 'text',
                    title: '📄 Дыхание - основа жизни человека',
                    content: 'Правильное дыхание - ключ к здоровью и долголетию. Практики осознанного дыхания.',
                    date: '2025-03-18',
                    author: 'Admin'
                },
                {
                    id: 8,
                    type: 'text',
                    title: '📄 О силе человека',
                    content: 'Источники внутренней силы. Как развивать и сохранять силу духа.',
                    date: '2025-03-19',
                    author: 'Admin'
                }
            ];
            setPosts(initialPosts);
            localStorage.setItem('mainFeedPosts', JSON.stringify(initialPosts));
        }

        const roles = getUserRoles();
        setUserRoles(roles);
    }, []);

    useEffect(() => {
        if (feedEndRef.current) {
            feedEndRef.current.scrollIntoView({ behavior: 'auto' });
        }
    }, [posts]);

    useEffect(() => {
        if (showAddForm && addFormRef.current) {
            setTimeout(() => {
                addFormRef.current.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 100);
        }
    }, [showAddForm]);

    useEffect(() => {
        if (audioRef.current) {
            audioRef.current.volume = volume;
            audioRef.current.playbackRate = playbackRate;

            const updateTime = () => setCurrentTime(audioRef.current.currentTime);
            const updateDuration = () => setDuration(audioRef.current.duration);

            audioRef.current.addEventListener('timeupdate', updateTime);
            audioRef.current.addEventListener('loadedmetadata', updateDuration);

            return () => {
                if (audioRef.current) {
                    audioRef.current.removeEventListener('timeupdate', updateTime);
                    audioRef.current.removeEventListener('loadedmetadata', updateDuration);
                }
            };
        }
    }, [volume, playbackRate, playingAudioId]);

    const isAdmin = userRoles.includes('admin');

    const handleAddPost = () => {
        if (!newPost.title || !newPost.content) {
            alert('Заполните заголовок и содержание');
            return;
        }

        const post = {
            id: Date.now(),
            ...newPost,
            date: new Date().toISOString().split('T')[0],
            author: 'Admin'
        };

        const updatedPosts = [...posts, post];
        setPosts(updatedPosts);
        localStorage.setItem('mainFeedPosts', JSON.stringify(updatedPosts));

        setNotification(post.title);
        setTimeout(() => setNotification(null), 5000);

        setNewPost({ type: 'text', title: '', content: '', url: '' });
        setShowAddForm(false);

        setTimeout(() => {
            if (feedEndRef.current) {
                feedEndRef.current.scrollIntoView({ behavior: 'smooth' });
            }
        }, 100);
    };

    const handleDeletePost = (id) => {
        if (window.confirm('Удалить эту запись?')) {
            const updatedPosts = posts.filter(post => post.id !== id);
            setPosts(updatedPosts);
            localStorage.setItem('mainFeedPosts', JSON.stringify(updatedPosts));
            if (playingAudioId === id) {
                setPlayingAudioId(null);
            }
        }
    };

    const handlePlayAudio = (postId, audioUrl) => {
        if (playingAudioId === postId) {
            if (audioRef.current) {
                if (audioRef.current.paused) {
                    audioRef.current.play();
                } else {
                    audioRef.current.pause();
                }
            }
        } else {
            setPlayingAudioId(postId);
            setCurrentTime(0);
            setDuration(0);
            setTimeout(() => {
                if (audioRef.current) {
                    audioRef.current.src = audioUrl;
                    audioRef.current.play();
                }
            }, 100);
        }
    };

    const handleStopAudio = () => {
        if (audioRef.current) {
            audioRef.current.pause();
            audioRef.current.src = '';
        }
        setPlayingAudioId(null);
        setCurrentTime(0);
        setDuration(0);
    };

    const handleVolumeChange = (e) => {
        setVolume(parseFloat(e.target.value));
    };

    const handleSpeedChange = (e) => {
        setPlaybackRate(parseFloat(e.target.value));
    };

    const togglePlayPause = () => {
        if (audioRef.current) {
            if (audioRef.current.paused) {
                audioRef.current.play();
            } else {
                audioRef.current.pause();
            }
        }
    };

    const handleSeek = (e) => {
        const newTime = parseFloat(e.target.value);
        setCurrentTime(newTime);
        if (audioRef.current) {
            audioRef.current.currentTime = newTime;
        }
    };

    const formatTime = (time) => {
        if (isNaN(time)) return '0:00';
        const mins = Math.floor(time / 60);
        const secs = Math.floor(time % 60);
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    return (
        <div className="main-feed">
            {notification && (
                <div className="event-notification">
                    <div className="notification-content">
                        <div className="notification-icon">🎉</div>
                        <div className="notification-text">
                            <strong>Новая запись!</strong>
                            <span>{notification}</span>
                        </div>
                        <div className="notification-close" onClick={() => setNotification(null)}>✕</div>
                    </div>
                </div>
            )}

            <div className="feed-header">
                <h2>📰 Лента проекта "Путь Сердца"</h2>
                <p>Свежие записи внизу, архивные вверху</p>
            </div>

            <div className="feed-container">
                <div className="feed-list">
                    {posts.map((post) => (
                        <div key={post.id} className="feed-post">
                            <div className="post-header">
                                <div className="post-title">{post.title}</div>
                                {isAdmin && (
                                    <button className="delete-post" onClick={() => handleDeletePost(post.id)}>
                                        🗑️
                                    </button>
                                )}
                            </div>
                            <div className="post-date">{post.date}</div>
                            <div className="post-content">{post.content}</div>

                            {post.type === 'audio' && (
                                <div className="post-audio">
                                    {playingAudioId === post.id ? (
                                        <div className="audio-player">
                                            <div className="audio-controls">
                                                <button className="play-btn" onClick={togglePlayPause}>
                                                    {audioRef.current && !audioRef.current.paused ? '⏸️' : '▶️'}
                                                </button>
                                                <button className="stop-btn" onClick={handleStopAudio}>⏹️</button>
                                                <div className="audio-progress">
                                                    <span>{formatTime(currentTime)}</span>
                                                    <input
                                                        type="range"
                                                        className="seek-bar"
                                                        min="0"
                                                        max={duration || 100}
                                                        value={currentTime}
                                                        onChange={handleSeek}
                                                    />
                                                    <span>{formatTime(duration)}</span>
                                                </div>
                                            </div>
                                            <div className="audio-settings">
                                                <div className="volume-control">
                                                    <span>🔊</span>
                                                    <input
                                                        type="range"
                                                        min="0"
                                                        max="1"
                                                        step="0.01"
                                                        value={volume}
                                                        onChange={handleVolumeChange}
                                                    />
                                                </div>
                                                <div className="speed-control">
                                                    <span>⚡</span>
                                                    <select value={playbackRate} onChange={handleSpeedChange}>
                                                        <option value="0.5">0.5x</option>
                                                        <option value="0.75">0.75x</option>
                                                        <option value="1.0">1.0x</option>
                                                        <option value="1.25">1.25x</option>
                                                        <option value="1.5">1.5x</option>
                                                        <option value="2.0">2.0x</option>
                                                    </select>
                                                </div>
                                            </div>
                                        </div>
                                    ) : (
                                        <button className="play-audio-btn" onClick={() => handlePlayAudio(post.id, post.url)}>
                                            ▶️ Слушать эфир
                                        </button>
                                    )}
                                </div>
                            )}

                            {post.type === 'video' && post.url && (
                                <div className="post-video">
                                    <video controls width="100%">
                                        <source src={post.url} type="video/mp4" />
                                    </video>
                                </div>
                            )}
                        </div>
                    ))}
                    <div ref={feedEndRef} className="feed-end-marker" />
                </div>

                {isAdmin && (
                    <div className="admin-section" ref={addFormRef}>
                        <div className="admin-panel">
                            <div className="admin-panel-header">
                                <h3>📝 Создать запись</h3>
                                <button className="toggle-panel-btn" onClick={() => setShowAddForm(!showAddForm)}>
                                    {showAddForm ? '−' : '+'}
                                </button>
                            </div>

                            {showAddForm && (
                                <div className="admin-panel-content">
                                    <input
                                        type="text"
                                        className="post-title-input"
                                        placeholder="Заголовок записи"
                                        value={newPost.title}
                                        onChange={(e) => setNewPost({...newPost, title: e.target.value})}
                                    />
                                    <textarea
                                        className="post-content-input"
                                        placeholder="Текст записи..."
                                        value={newPost.content}
                                        onChange={(e) => setNewPost({...newPost, content: e.target.value})}
                                        rows="4"
                                    />
                                    <div className="media-attachments">
                                        <label className="attach-button">
                                            📎 Прикрепить файл
                                            <input
                                                type="file"
                                                accept="audio/*,video/*"
                                                onChange={(e) => {
                                                    const file = e.target.files[0];
                                                    if (file) {
                                                        const url = URL.createObjectURL(file);
                                                        const type = file.type.startsWith('audio/') ? 'audio' : 'video';
                                                        setNewPost({...newPost, type, url});
                                                    }
                                                }}
                                                style={{ display: 'none' }}
                                            />
                                        </label>
                                        {newPost.url && (
                                            <span className="attached-file">
                                                📁 Файл выбран
                                                <button onClick={() => setNewPost({...newPost, url: '', type: 'text'})}>✕</button>
                                            </span>
                                        )}
                                    </div>
                                    <div className="post-type-selector">
                                        <button className={`type-btn ${newPost.type === 'text' ? 'active' : ''}`} onClick={() => setNewPost({...newPost, type: 'text', url: ''})}>📄 Текст</button>
                                        <button className={`type-btn ${newPost.type === 'audio' ? 'active' : ''}`} onClick={() => setNewPost({...newPost, type: 'audio'})}>🎵 Аудио</button>
                                        <button className={`type-btn ${newPost.type === 'video' ? 'active' : ''}`} onClick={() => setNewPost({...newPost, type: 'video'})}>🎬 Видео</button>
                                    </div>
                                    <button className="publish-btn" onClick={handleAddPost}>📤 Опубликовать</button>
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>

            <audio ref={audioRef} style={{ display: 'none' }} />
        </div>
    );
};

export default MainFeed;
